// Seleccionar el backup más reciente VÁLIDO para probar la restauración.
// Válido = existe, pesa > 1 KB y pg_restore --list finaliza con código 0 y objetos > 0.
// El --list solo sirve para elegir el archivo candidato: NO es prueba de restauración.
const fs = require('fs');
const { execSync } = require('child_process');
const DIR = '/data/backups';

let result;
try {
  const candidates = fs.readdirSync(DIR)
    .filter(f => /^gymbro-backup-.*\.dump$/.test(f))
    .map(f => {
      try {
        const st = fs.statSync(DIR + '/' + f);
        return { filename: f, backupPath: DIR + '/' + f, size: st.size, mtimeMs: st.mtimeMs };
      } catch {
        return null;
      }
    })
    .filter(c => c && c.size > 1024)
    .sort((a, b) => b.mtimeMs - a.mtimeMs);

  let chosen = null;
  for (const c of candidates) {
    let objetos = 0, exitCode = 0;
    try {
      const out = execSync('pg_restore --list ' + JSON.stringify(c.backupPath), { encoding: 'utf8', shell: '/bin/sh', maxBuffer: 10 * 1024 * 1024 });
      objetos = out.split('\n').filter(l => l.trim().length > 0).length;
    } catch (e) {
      exitCode = typeof e.status === 'number' ? e.status : 1;
    }
    if (exitCode === 0 && objetos > 0) { chosen = { ...c, objetos }; break; }
  }

  if (!chosen) {
    result = {
      selectionOk: false,
      filename: '', backupPath: '', objetos: 0,
      etapa: 'seleccionar', motivo: 'No hay ningún .dump válido (>1 KB, legible por pg_restore, objetos>0) en /data/backups',
      startedAt: new Date().toISOString()
    };
  } else {
    result = {
      ...chosen,
      selectionOk: true,
      etapa: '', motivo: '',
      startedAt: new Date().toISOString()
    };
  }
} catch (e) {
  result = {
    selectionOk: false,
    filename: '', backupPath: '', objetos: 0,
    etapa: 'seleccionar', motivo: String(e.message || e),
    startedAt: new Date().toISOString()
  };
}

return [{ json: result }];

