// Restaurar el .dump seleccionado DENTRO de la base de pruebas (restore_test, aislada).
// Jamás se toca la base principal de Gymbro.
const { execSync } = require('child_process');
const sel = $('Seleccionar Backup Válido').all()[0].json;
if (!sel.selectionOk) {
  return [{ json: { restoreStepOk: false, restoreExitCode: -1, restoreError: 'selección previa fallida', etapa: 'restaurar', motivo: sel.motivo || 'pasos previos fallidos' } }];
}

const cmd = '. /data/restore-test-config.env && pg_restore --exit-on-error --no-owner --no-privileges '
  + '-h "$RESTORE_TEST_HOST" -p "$RESTORE_TEST_PORT" -U "$RESTORE_TEST_USER" -d restore_test ' + JSON.stringify(sel.backupPath);
try {
  execSync(cmd, { encoding: 'utf8', shell: '/bin/sh', maxBuffer: 64 * 1024 * 1024 });
  return [{ json: { restoreStepOk: true, restoreExitCode: 0, restoreError: '' } }];
} catch (e) {
  const stderr = e.stderr ? e.stderr.toString() : String(e.message || e);
  const code = typeof e.status === 'number' ? e.status : 1;
  return [{ json: { restoreStepOk: false, restoreExitCode: code, restoreError: stderr, etapa: 'restaurar', motivo: 'pg_restore falló al restaurar: ' + stderr } }];
}

