// Registrar resultado de la prueba en /data/informes/restore-test-log.txt
const fs = require('fs');
const safe = (name) => { try { const a = $(name).all(); return (a[0] && a[0].json) ? a[0].json : {}; } catch (_) { return {}; } };
const sel = safe('Seleccionar Backup Válido');
const rs = safe('Restaurar Backup');
const ct = safe('Contar Tablas');
const vf = safe('Verificar Filas (> 0)');
const cl = safe('Limpiar Scratch (Final)');
const stamp = new Date().toISOString();

const selOk = !!sel.selectionOk;
const rsOk = !!rs.restoreStepOk;
const filasNum = vf && typeof vf.filas !== 'undefined' ? Number(vf.filas) : NaN;
const rowsOk = !Number.isNaN(filasNum) && filasNum > 0;
const tablasCount = ct && typeof ct.tablas !== 'undefined' ? Number(ct.tablas) : 0;
const tablesCount = !Number.isNaN(tablasCount) ? tablasCount : 0;
let rowsReason = '';
if (!rowsOk) {
  if (vf && vf.message) rowsReason = 'error: ' + String(vf.message).slice(0, 200);
  else if (Number.isNaN(filasNum)) rowsReason = 'el nodo de verificación no devolvió el conteo de registros';
  else rowsReason = 'sin registros restaurados';
}
const restoreOk = selOk && rsOk && tablesCount > 0 && rowsOk;
const resultado = restoreOk ? 'restore_ok' : 'restore_fallido';

let etapa = '-', motivo = '-';
if (!selOk) { etapa = 'seleccionar'; motivo = sel.motivo || 'no hay dump válido'; }
else if (!rsOk) { etapa = 'restaurar'; motivo = rs.motivo || 'pg_restore falló'; }
else if (tablesCount <= 0) { etapa = 'comprobar'; motivo = vf && vf.message ? ('error SQL: ' + String(vf.message).slice(0, 200)) : 'cero tablas de usuario tras la restauración'; }
else if (!rowsOk) { etapa = 'comprobar'; motivo = rowsReason || 'sin registros restaurados'; }

const filas = rowsOk ? Number(vf.filas) : 0;
const cleanupOk = cl && cl.estado === 'cleaned';
const line = `[${stamp}] resultado=${resultado} | archivo=${sel.filename || '-'} | objetos=${sel.objetos || 0} | tablas=${tablesCount} | filas=${filas} | limpieza=${cleanupOk ? 'OK' : 'SIN CONFIRMAR'} | etapa=${etapa} | error=${motivo}\n`;
let logWritten = false, logError = '';
try {
  fs.appendFileSync('/data/informes/restore-test-log.txt', line, 'utf8');
  logWritten = true;
} catch (e) {
  logError = String(e.message || e);
}

console.log('[WF-RESTORE]', line.trim());
return [{ json: { resultado, etapa, motivo, tablas: tablesCount, cleanupOk, logWritten, logError, restoreOk, startedAt: sel.startedAt, filename: sel.filename } }];
